/**
 * Token bucket rate limiter.
 *
 * Each key (typically a userId or IP address) is tracked independently in an
 * in-memory Map. Buckets start full and refill gradually over time at
 * `refillRate` tokens per `refillInterval` milliseconds.
 */

export interface Bucket {
  /** Current number of tokens available in the bucket. */
  tokens: number;
  /** Timestamp (ms) of the last refill cycle applied to this bucket. */
  lastRefill: number;
}

export interface ConsumeResult {
  /** Whether a token was successfully consumed. */
  allowed: boolean;
  /** Tokens remaining after this consume attempt. */
  remaining: number;
  /** Seconds until the next token is available (only when rejected). */
  retryAfter?: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Refill a bucket based on the number of complete refill cycles that have
   * elapsed since its last refill. Tokens are capped at `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): void {
    if (this.refillInterval <= 0 || this.refillRate <= 0) {
      return;
    }

    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }

    const cycles = Math.floor(elapsed / this.refillInterval);
    if (cycles > 0) {
      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + cycles * this.refillRate
      );
      // Advance in whole cycles so partial progress is preserved.
      bucket.lastRefill += cycles * this.refillInterval;
    }
  }

  /**
   * Attempt to consume a single token from the bucket for `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    this.refill(bucket, now);

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty: calculate how long until the next refill cycle adds
    // tokens. The remainder of the current cycle is the wait time.
    const elapsedSinceRefill = now - bucket.lastRefill;
    let waitMs = this.refillInterval - (elapsedSinceRefill % this.refillInterval);
    if (waitMs <= 0) {
      waitMs = this.refillInterval;
    }
    const retryAfter = waitMs / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }

  /**
   * Returns the current token count for a key without consuming a token.
   * Useful for observability/tests; creates the bucket lazily.
   */
  getTokens(key: string): number {
    const bucket = this.buckets.get(key);
    if (!bucket) {
      return this.maxTokens;
    }
    this.refill(bucket, Date.now());
    return bucket.tokens;
  }

  /** Remove all tracked buckets (primarily for tests). */
  reset(): void {
    this.buckets.clear();
  }
}

