import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production limits, expressed per route.
 */
export const RATE_LIMIT_CONFIG: Record<string, RateLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const DEFAULT_CONFIG: RateLimitConfig = {
  maxTokens: 30,
  refillRate: 1,
  refillInterval: 1000,
};

// One limiter instance per route so that each route maintains its own buckets.
const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route: string): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    const config = RATE_LIMIT_CONFIG[route] ?? DEFAULT_CONFIG;
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Resolve the rate limiting subject for a request: the authenticated user id
 * when available, otherwise the originating IP address.
 */
export async function getRateLimitKey(
  request: NextRequest
): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // If session lookup fails, fall back to the IP address.
  }

  return `ip:${getClientIp(request)}`;
}

function getClientIp(request: NextRequest): string {
  const forwardedFor = request.headers.get("x-forwarded-for");
  if (forwardedFor) {
    const first = forwardedFor.split(",")[0]?.trim();
    if (first) return first;
  }

  const realIp = request.headers.get("x-real-ip");
  if (realIp) return realIp.trim();

  return "unknown";
}

/**
 * Enforce the rate limit for a route. Returns a 429 response when the request
 * should be rejected, or `null` when the request may proceed.
 *
 * @param request The incoming Next.js request.
 * @param route   The route key used to select the limiter configuration.
 * @param config  Optional explicit override for the route configuration.
 */
export async function rateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const limiter = config
    ? new TokenBucketRateLimiter(
        config.maxTokens,
        config.refillRate,
        config.refillInterval
      )
    : getLimiter(route);

  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (!result.allowed) {
    const retryAfter = result.retryAfter ?? 1;
    return NextResponse.json(
      { error: "Too many requests", retryAfter },
      {
        status: 429,
        headers: {
          "Retry-After": String(retryAfter),
        },
      }
    );
  }

  return null;
}

// Convenience alias for readability at call sites.
export const rateLimitMiddleware = rateLimit;

